class RequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[Any] = None) -> None:
        super().__init__(errors)
        self.body = body
        self.endpoint_context = endpoint_context

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\n"
        for err in self._errors:
            message += f"  {err}\n"

        if self.endpoint_context:
            context_str = (
                f"\n  File \"{self.endpoint_context.filepath}\", line {self.endpoint_context.lineno}, in {self.endpoint_context.func_name}\n"
                f"    {self.endpoint_context.method} {self.endpoint_context.route}"
            )
            message += context_str
        return message

